python3 -c "
import json, statistics
files = {
    'Qwen_SciERC_beam': '/root/schema_semantic_constrained_ie/outputs/beam_search_scierc_full_551.jsonl',
    'Llama_SciERC_beam': '/root/schema_semantic_constrained_ie/outputs/llama_scierc_beam_full_s1_551.jsonl',
    'Qwen_DocRED_beam': '/root/schema_semantic_constrained_ie/outputs/w9_qwen_docred_beam_50.jsonl',
    'Llama_DocRED_beam': '/root/schema_semantic_constrained_ie/outputs/docred_llama_beam_50.jsonl',
}
for name, path in files.items():
    times = []
    try:
        with open(path) as f:
            for line in f:
                doc = json.loads(line)
                for k in ['inference_time_seconds', 'inference_time', 'time_seconds']:
                    if k in doc:
                        times.append(doc[k])
                        break
        if times:
            print(f'{name}: n={len(times)}, mean={statistics.mean(times):.3f}, std={statistics.stdev(times):.3f}')
        else:
            print(f'{name}: no time field found. keys={list(json.loads(open(path).readline()).keys())[:10]}')
    except Exception as e:
        print(f'{name}: ERROR {e}')
"

